// Turns DOSSIER_LOGIN_PASSWORD (generated by the Railway template) into the
// argon2id hash that Dossier expects in DOSSIER_PASSWORD, and prints it.
//
// Dossier only accepts a hash, written as
//   argon2id:m=<KiB>,t=<passes>,p=<lanes>:<salt base64url>:<hash base64url>
// (see "Sign-in" in Dossier's DEVELOPMENT.md and SECURITY.md). This file is
// an independent implementation of that format with node:crypto, using the
// same argon2id settings as Dossier's own `hash-password` tool.
//
// The salt is derived from DOSSIER_SECRET instead of being random, so the
// same password gives the same hash on every boot. Dossier binds each
// session to a fingerprint of DOSSIER_PASSWORD; a fresh random salt per boot
// would sign the user out on every restart or redeploy. Changing the password
// or DOSSIER_SECRET still changes the hash and ends every session, as
// upstream intends.
//
// Usage:
//   node railway-password.mjs              reads DOSSIER_LOGIN_PASSWORD and DOSSIER_SECRET,
//                                          prints the hash on stdout
//   node railway-password.mjs --self-test  build-time check of node:crypto argon2 and the format

import crypto from "node:crypto";
import { pathToFileURL } from "node:url";

const SALT_CONTEXT = "dossier-railway-template/login-password-salt/v1";
const SALT_BYTES = 16;
const HASH_BYTES = 32;
// OWASP's argon2id recommendation, as used by Dossier's hash-password: 19 MiB, 2 passes, 1 lane.
const PARAMS = Object.freeze({ memory: 19_456, passes: 2, parallelism: 1 });
const MIN_PASSWORD_LENGTH = 12;
const MIN_SECRET_LENGTH = 32;
// The shape Dossier's environment check accepts for DOSSIER_PASSWORD.
const HASH_SHAPE = /^argon2id:m=(\d{1,7}),t=(\d{1,3}),p=(\d{1,3}):([\w-]{22,}):([\w-]{43,})$/;
const MAX_MEMORY_KIB = 262_144;

const fail = (message) => {
  process.stderr.write(`[railway-password] ${message}\n`);
  return 1;
};

/** A salt that is unique per install (keyed by DOSSIER_SECRET) and stable across boots. */
export function deriveSalt(secret) {
  return crypto.createHmac("sha256", secret).update(SALT_CONTEXT).digest().subarray(0, SALT_BYTES);
}

/** The DOSSIER_PASSWORD value for `password`. */
export function hashLoginPassword(password, secret) {
  if (typeof crypto.argon2Sync !== "function") {
    throw new Error(`Node ${process.version} has no crypto.argon2Sync (Node 24.7 or newer is needed).`);
  }
  const salt = deriveSalt(secret);
  const tag = crypto.argon2Sync("argon2id", {
    message: password,
    nonce: salt,
    memory: PARAMS.memory,
    passes: PARAMS.passes,
    parallelism: PARAMS.parallelism,
    tagLength: HASH_BYTES,
  });
  const { memory, passes, parallelism } = PARAMS;
  return `argon2id:m=${memory},t=${passes},p=${parallelism}:${salt.toString("base64url")}:${Buffer.from(tag).toString("base64url")}`;
}

/** Whether `value` has the shape and limits Dossier accepts. */
export function looksLikeDossierHash(value) {
  const match = HASH_SHAPE.exec(value);
  if (!match) return false;
  const [memory, passes, parallelism] = match.slice(1, 4).map(Number);
  return passes >= 1 && parallelism >= 1 && memory >= 8 * parallelism && memory <= MAX_MEMORY_KIB;
}

/** Why `password` can't be used, or null. Never includes the password. */
export function passwordProblem(password) {
  if (!password) return "DOSSIER_LOGIN_PASSWORD is empty.";
  if (password !== password.trim()) return "DOSSIER_LOGIN_PASSWORD starts or ends with whitespace; remove it.";
  if (/\p{Cc}/u.test(password)) return "DOSSIER_LOGIN_PASSWORD contains control characters (a line break?).";
  const length = Array.from(password).length;
  if (length < MIN_PASSWORD_LENGTH) {
    return `DOSSIER_LOGIN_PASSWORD is too short (${length} characters); use at least ${MIN_PASSWORD_LENGTH}.`;
  }
  return null;
}

/** Why `secret` can't be used, or null. Never includes the secret. */
export function secretProblem(secret) {
  if (!secret || secret.trim() === "") return "DOSSIER_SECRET is not set.";
  if (secret.length < MIN_SECRET_LENGTH) {
    return `DOSSIER_SECRET is too short (${secret.length} characters); Dossier needs at least ${MIN_SECRET_LENGTH}.`;
  }
  return null;
}

function selfTest() {
  const secret = "s".repeat(MIN_SECRET_LENGTH);
  const first = hashLoginPassword("correct horse battery staple", secret);
  const again = hashLoginPassword("correct horse battery staple", secret);
  const otherPassword = hashLoginPassword("correct horse battery stapler", secret);
  const otherSecret = hashLoginPassword("correct horse battery staple", "t".repeat(MIN_SECRET_LENGTH));
  const checks = [
    [looksLikeDossierHash(first), "hash has Dossier's DOSSIER_PASSWORD shape"],
    [first === again, "same password and secret give the same hash"],
    [first !== otherPassword, "another password gives another hash"],
    [first.split(":")[2] !== otherSecret.split(":")[2], "another DOSSIER_SECRET gives another salt"],
    [passwordProblem("short") !== null, "short passwords are refused"],
    [secretProblem("x".repeat(31)) !== null, "short secrets are refused"],
  ];
  const failed = checks.filter(([ok]) => !ok).map(([, name]) => name);
  if (failed.length > 0) return fail(`self-test failed: ${failed.join("; ")}`);
  process.stdout.write(`[railway-password] self-test passed on Node ${process.version}\n`);
  return 0;
}

function main(argv) {
  if (argv.includes("--self-test")) return selfTest();
  const password = process.env.DOSSIER_LOGIN_PASSWORD ?? "";
  const secret = process.env.DOSSIER_SECRET ?? "";
  const problem = passwordProblem(password) ?? secretProblem(secret);
  if (problem) return fail(problem);
  const hash = hashLoginPassword(password, secret);
  if (!looksLikeDossierHash(hash)) return fail("the computed hash does not have the shape Dossier expects.");
  process.stdout.write(`${hash}\n`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (error) {
    process.exitCode = fail(error instanceof Error ? error.message : String(error));
  }
}
